const connectionString = process.env.TEST_DATABASE_URL;
async function countPoolStatements<T>(pool:Pool,work:()=>Promise<T>):Promise<{value:T;statements:number}>{
  const countedPool=pool as unknown as {query:(...args:unknown[])=>unknown},originalQuery=countedPool.query;let statements=0;
  countedPool.query=(...args:unknown[])=>{statements++;return originalQuery.apply(pool,args);};
  try{return{value:await work(),statements};}finally{countedPool.query=originalQuery;}
}

